import functools

def _parse(v):
    core = v.split('+', 1)[0]
    if '-' in core:
        main, pre = core.split('-', 1)
    else:
        main, pre = core, None
    major, minor, patch = (int(x) for x in main.split('.'))
    pre_ids = pre.split('.') if pre is not None else None
    return (major, minor, patch, pre_ids)

def _cmp_id(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if a_num and not b_num:
        return -1
    if not a_num and b_num:
        return 1
    return (a > b) - (a < b)

def _cmp(v1, v2):
    m1, n1, p1, pre1 = _parse(v1)
    m2, n2, p2, pre2 = _parse(v2)
    for x, y in ((m1, m2), (n1, n2), (p1, p2)):
        if x != y:
            return (x > y) - (x < y)
    if pre1 is None and pre2 is None:
        return 0
    if pre1 is None and pre2 is not None:
        return 1
    if pre1 is not None and pre2 is None:
        return -1
    for a, b in zip(pre1, pre2):
        c = _cmp_id(a, b)
        if c != 0:
            return c
    return (len(pre1) > len(pre2)) - (len(pre1) < len(pre2))

def semver_sort(versions):
    return sorted(versions, key=functools.cmp_to_key(_cmp))

